"""Exact MATLAB/Simulink generated SPS load-model bank.

Contains the generated 15-state plant realizations for nominal balanced
resistive loads of 40, 50 and 60 kW.  These matrices were extracted from the
corresponding *_data.cpp files (S.A, S.B, S.C, S.D, S.x0).

IMPORTANT: X0 is for episode initialization only.  During an in-run load step,
preserve the current electrical state x and switch only A/B/C/D.
"""
from dataclasses import dataclass
import numpy as np

@dataclass(frozen=True)
class LoadModel:
    power_w: float
    resistance_ohm: float
    A: np.ndarray
    B: np.ndarray
    C: np.ndarray
    D: np.ndarray
    X0: np.ndarray

    def copies(self):
        return (self.A.copy(), self.B.copy(), self.C.copy(), self.D.copy(), self.X0.copy())

