X0_60KW = np.array([-6076163.7315489575, 108924.09588544453, 22161161.041316316, 307301.0503241426, -16084997.309767354, 119.78442956080819, -436.9201496532595, -173090.2335415121, -89.73755815280387, -79989.14943508757, 2905184.7753873486, 71.20308969222941, 253079.38297659947, -9186730.067025041, 18.53446846078104], dtype=np.float64)

LOAD_60KW = LoadModel(
    power_w=60000.0,
    resistance_ohm=V_LL_NOMINAL**2 / 60000.0,
    A=A_60KW, B=B_60KW, C=C_60KW, D=D_60KW, X0=X0_60KW,
)

LOAD_MODELS = {
    40000: LOAD_40KW,
    50000: LOAD_50KW,
    60000: LOAD_60KW,
}

def available_loads():
    return tuple(sorted(LOAD_MODELS))

def get_load_model(power_w: float, *, atol: float = 1e-6) -> LoadModel:
    p = float(power_w)
    for key, model in LOAD_MODELS.items():
        if abs(p - key) <= atol:
            return model
    raise ValueError(
        f"No exact generated load model for {p:g} W. "
        f"Available exact models: {available_loads()} W."
    )

def validate_load_models():
    for p, model in LOAD_MODELS.items():
        assert model.A.shape == (15, 15)
        assert model.B.shape == (15, 10)
        assert model.C.shape == (19, 15)
        assert model.D.shape == (19, 10)
        assert model.X0.shape == (15,)
        assert all(np.isfinite(x).all() for x in (model.A, model.B, model.C, model.D, model.X0))
        assert np.isclose(model.resistance_ohm, V_LL_NOMINAL**2 / p)
    return True

if __name__ == "__main__":
    validate_load_models()
    print("Exact generated load models:")
    for p in available_loads():
        m = get_load_model(p)
        print(f"  {p/1000:.0f} kW: R = {m.resistance_ohm:.6f} ohm, X0 shape={m.X0.shape}")
